from pathlib import Path
import hashlib,json,struct
D=Path(__file__).resolve().parent;M=D.parent/'motor-wires'
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def read(n):return json.loads((D/n).read_text())
def bounds(p):
 b=Path(p).read_bytes();n=struct.unpack_from('<I',b,80)[0];assert len(b)==84+50*n
 vs=[struct.unpack_from('<3f',b,84+50*i+12+12*j)for i in range(n)for j in range(3)]
 return [[min(v[k]for v in vs)for k in range(3)],[max(v[k]for v in vs)for k in range(3)]]
r=read('ankle-route-check.json');f=read('final-source-check.json');s=read('self-check.json');p=read('preplugged-delta.json');a=read('plug-access.json');top=json.loads((M/'active-topology.json').read_text())
for q in [r,f]:
 for file,h in q['sourceHashes'].items():assert sha(file)==h,(file,'changed source')
assert r['complete'] and r['passedStatic'] and s['passed'] and p['passed'] and f['complete']
assert s['sourceSha256']==sha(D/'ankle-route-check.json')
