 routes.append({'id':rid,'fromPort':rr['fromPort'],'toPort':rr['toPort'],'nominalStockLengthMm':180,'individualCenterlineLengthsMm':[w['centerlineLengthMm']for w in r['strands']if w['routeId']==rid],'diameterReceivingMm':1.5,'localBendRadiusAssumptionMm':2,'slackBendRadiusAssumptionMm':4,'routePrimitivesFile':str(D/'ankle-route-check.json'),'pinOrderEncodedByStrandOrColor':False,'targetWireRearSlotOffsetFromMaxEnvelopeShoulderMm':-.6,'rearSlotEvidence':'JST EH catalogue housing profile 6.5 mm body plus 0.6 mm protrusions; wire bend begins within rear receiving profile, not at maximum abstract bounding shoulder. Connector pose is unchanged; this is not a measured internal-slot or minimum-bend specification.'})
